#ifndef QUANTITY_HPP
#define QUANTITY_HPP

#include "../concepts/numeric.hpp"

namespace dmath {
template<numeric T, class Unit>
class quantity
{
private:
    T data;

public:
    using quantity_t = quantity<T, Unit>;
    constexpr explicit quantity(T value): data(value) {};

    constexpr quantity_t operator+(const quantity_t& other) const {
        return {.data = this->data-other.data};
    }
    constexpr quantity_t operator-(const quantity_t& other) const {
        return {.data = this->data-other.data};
    }
    // operator!= is auto-generated by C++20 by overload of operator==
    constexpr bool operator==(const quantity_t& other) const {
        return (this->data == other.data) ? true : false;
    }
    constexpr auto operator<=>(const quantity_t& other) const = default;
    constexpr quantity_t operator+() const;
    constexpr quantity_t operator-() const;
    constexpr quantity_t operator*(const T factor) { return this->data*factor; }
    constexpr quantity_t operator/(const T factor) { return this->data/factor; }
    constexpr quantity<T, class returnUnit> operator*(const quantity<T, class parameterUnit>& other) const {
        quantity<T, returnUnit> qt(this->data*other.data);
        return qt;
    }
    constexpr quantity<T, class returnUnit> operator/(const quantity<T, class parameterUnit>& other) const {
        quantity<T, returnUnit> qt(this->data/other.data);
        return qt;
    }
};
} // !NAMESPACE DMATH

#endif // QUANTITY_HPP
